import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1793898870000}'),r={name:"guide/architecture.md"};function c(l,t,i,n,s,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>gsh 是微内核 + 插件化结构，分层如下：</p><table tabindex="0"><thead><tr><th>层</th><th>职责</th></tr></thead><tbody><tr><td><code>kernel</code></td><td>微内核：插件加载、依赖注入（<code>Use[T]</code>）、配置与作用域生命周期。</td></tr><tr><td><code>api</code></td><td>类型化服务接口（LLM / Tool / ToolRegistry / SessionStore / Loop / Event）。插件只依赖此层，互不直接 import。</td></tr><tr><td><code>loop</code></td><td>Agent 主循环：把用户输入跑成流式事件（delta / tool_call / tool_result），通过 channel 回流。</td></tr><tr><td><code>session</code></td><td>append-only JSONL 会话存储：resume / fork / 删除，标题取首条用户消息摘要。</td></tr><tr><td><code>tools</code></td><td>工具注册表 + 权限闸门（guard）+ 审计日志（audit）+ 审批器（approver）。写类工具内嵌统一 diff。</td></tr><tr><td><code>tui</code> / <code>web</code></td><td>两个对等的展示面，都消费 loop 的流式事件，不引入新 agent 逻辑。</td></tr></tbody></table><h2 id="事件回流" tabindex="-1">事件回流 <a class="header-anchor" href="#事件回流" aria-label="Permalink to &quot;事件回流&quot;">​</a></h2><p>loop 在独立 goroutine 顺序执行工具调用；TUI 用 channel 把事件桥接回 bubbletea 的 Update，实现逐字流与工具行实时状态。Web UI 走同样的事件模型，只是渲染到浏览器 DOM。</p>',5)])])}const _=e(r,[["render",c]]);export{u as __pageData,_ as default};
